CREATE VIEW VW_MERCATIPRESENZETOTALI AS 
SELECT 'STORICO' AS ORIGINE, IDCOMUNE, ANNO, CODICEANAGRAFE, FK_AUTORIZZAZIONI_ID, FKCODICEMERCATO, FKIDMERCATIUSO, FK_IDPOSTEGGIO AS FKIDPOSTEGGIO, NUMEROPRESENZE FROM MERCATIPRESENZE_STORICO
UNION
SELECT 'CALENDARIO' AS ORIGINE, MERCATIPRESENZE_T.IDCOMUNE, MERCATIPRESENZE_T.ANNO, MERCATIPRESENZE_D.CODICEANAGRAFE, MERCATIPRESENZE_D.FK_AUTORIZZAZIONI_ID, MERCATIPRESENZE_T.FKCODICEMERCATO, MERCATIPRESENZE_T.FKIDMERCATIUSO, MERCATIPRESENZE_D.FKIDPOSTEGGIO, 1 AS NUMEROPRESENZE FROM MERCATIPRESENZE_D, MERCATIPRESENZE_T WHERE MERCATIPRESENZE_D.IDCOMUNE = MERCATIPRESENZE_T.IDCOMUNE AND MERCATIPRESENZE_D.FKIDTESTATA = MERCATIPRESENZE_T.ID AND MERCATIPRESENZE_D.CODICEANAGRAFE IS NOT NULL
